update country_flag_history set image_url = '/flags/history/cy-0000.svg' where id = 2109 and iso_code = 'cy';
update country_flag_history set label_fr = 'Premier dessin (1960)', label_en = 'First design (1960)', notes_fr = 'Première version du drapeau de la future république : la silhouette de l''île n''est encore qu''un contour au-dessus des deux rameaux d''olivier.', notes_en = 'First version of the future republic''s flag: the island is still only an outline above the two olive branches.' where id = 2341 and iso_code = 'cy';
update country_flag_history set label_fr = 'République de Chypre (1960-2006)', label_en = 'Republic of Cyprus (1960–2006)', notes_fr = 'Drapeau de l''indépendance (16 août 1960) : l''île couleur cuivre rappelle le métal qui porte son nom, et les rameaux d''olivier la paix entre Chypriotes grecs et turcs. Il est légèrement retouché en 2006.', notes_en = 'The independence flag (16 August 1960): the copper-coloured island recalls the metal that bears its name, and the olive branches peace between Greek and Turkish Cypriots. It was slightly revised in 2006.' where id = 2342 and iso_code = 'cy';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cy', '/flags/history/cy-1881.svg', '1881-01-01', '1922-01-01', 'Chypre sous administration britannique (1881-1922)', 'British-administered Cyprus (1881–1922)', 'Premier pavillon colonial : un Blue Ensign chargé du badge de l''île, alors encore possession ottomane administrée par le Royaume-Uni.', 'First colonial flag: a Blue Ensign bearing the island''s badge, at a time when Cyprus was still Ottoman territory run by Britain.');
